def transform(grid):
    h=len(grid); w=len(grid[0])
    out=[row[:] for row in grid]
    for r in range(h):
        cols=[c for c,v in enumerate(grid[r]) if v==8]
        if cols:
            c0=min(cols)
            for c in range(c0,w): out[r][c]=8
        else:
            for c in range(w): out[r][c]=8
    return out
